class Solution { public: int shortestPathBinaryMatrix(vector<vector<int>>& grid){int n=grid.size();if(grid[0][0]||grid[n-1][n-1])return -1;queue<array<int,3>> pending;pending.push({0,0,1});grid[0][0]=1;while(!pending.empty()){auto cell=pending.front();pending.pop();if(cell[0]==n-1&&cell[1]==n-1)return cell[2];for(int dr=-1;dr<=1;++dr)for(int dc=-1;dc<=1;++dc){int r=cell[0]+dr,c=cell[1]+dc;if((dr||dc)&&r>=0&&r<n&&c>=0&&c<n&&!grid[r][c]){grid[r][c]=1;pending.push({r,c,cell[2]+1});}}}return -1;} };
